var ErrIncidentNotFound = errors.New("storage: incidente no encontrado")

// DetectorStat agrega conteo por detector en un rango temporal.
type DetectorStat struct {
	Detector string `json:"detector"`
	Count    int64  `json:"count"`
}

// InsertIncident persiste un incidente y rellena ID y CreatedAt.
func (s *Store) InsertIncident(ctx context.Context, inc *Incident) error {
	if inc.ID == uuid.Nil {
		inc.ID = uuid.New()
	}
	const q = `
		INSERT INTO incidents (
			id, guild_id, detector, user_id, channel_id,
			score, action, reason, evidence, created_at
		) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9, NOW())
		RETURNING created_at`

	err := s.pool.QueryRow(ctx, q,
		inc.ID, inc.GuildID, inc.Detector, inc.UserID, inc.ChannelID,
		inc.Score, inc.Action, inc.Reason, inc.Evidence,
	).Scan(&inc.CreatedAt)
	if err != nil {
		return fmt.Errorf("storage: insert incident: %w", err)
	}
	return nil
}

// GetIncident carga un incidente por ID.
func (s *Store) GetIncident(ctx context.Context, id uuid.UUID) (*Incident, error) {
	const q = `
		SELECT id, guild_id, detector, user_id, channel_id,
		       score, action, reason, evidence, created_at,
		       resolved_at, resolved_by
		FROM incidents WHERE id = $1`

	var inc Incident
	err := s.pool.QueryRow(ctx, q, id).Scan(
		&inc.ID, &inc.GuildID, &inc.Detector, &inc.UserID, &inc.ChannelID,
		&inc.Score, &inc.Action, &inc.Reason, &inc.Evidence, &inc.CreatedAt,
		&inc.ResolvedAt, &inc.ResolvedBy,
	)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, ErrIncidentNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("storage: get incident %s: %w", id, err)
	}
	return &inc, nil
}

