func (s *Store) ListRecentIncidents(ctx context.Context, guildID string, limit int) ([]Incident, error) {
	if limit <= 0 || limit > 200 {
		limit = 25
	}
	const q = `
		SELECT id, guild_id, detector, user_id, channel_id,
		       score, action, reason, created_at
		FROM incidents
		WHERE guild_id = $1
		ORDER BY created_at DESC
		LIMIT $2`

	rows, err := s.pool.Query(ctx, q, guildID, limit)
	if err != nil {
		return nil, fmt.Errorf("storage: list incidents: %w", err)
	}
	defer rows.Close()

	out := make([]Incident, 0, limit)
	for rows.Next() {
		var inc Incident
		if err := rows.Scan(
			&inc.ID, &inc.GuildID, &inc.Detector, &inc.UserID, &inc.ChannelID,
			&inc.Score, &inc.Action, &inc.Reason, &inc.CreatedAt,
		); err != nil {
			return nil, fmt.Errorf("storage: scan incident: %w", err)
		}
		out = append(out, inc)
	}
	return out, rows.Err()
}

// ListIncidentsByUser devuelve el historial de un usuario en el guild.
func (s *Store) ListIncidentsByUser(ctx context.Context, guildID, userID string, limit int) ([]Incident, error) {
	if limit <= 0 || limit > 100 {
		limit = 20
	}
	const q = `
		SELECT id, guild_id, detector, user_id, channel_id,
		       score, action, reason, created_at
		FROM incidents
		WHERE guild_id = $1 AND user_id = $2
		ORDER BY created_at DESC
		LIMIT $3`

	rows, err := s.pool.Query(ctx, q, guildID, userID, limit)
	if err != nil {
		return nil, fmt.Errorf("storage: list user incidents: %w", err)
	}
	defer rows.Close()

	out := make([]Incident, 0, limit)
	for rows.Next() {
		var inc Incident
		if err := rows.Scan(
			&inc.ID, &inc.GuildID, &inc.Detector, &inc.UserID, &inc.ChannelID,
			&inc.Score, &inc.Action, &inc.Reason, &inc.CreatedAt,
		); err != nil {
			return nil, fmt.Errorf("storage: scan user incident: %w", err)
		}
		out = append(out, inc)
	}
	return out, rows.Err()
}

// CountIncidentsSince cuenta incidentes desde un instante dado.
func (s *Store) CountIncidentsSince(ctx context.Context, guildID string, since time.Time) (int64, error) {
	const q = `SELECT COUNT(*) FROM incidents WHERE guild_id = $1 AND created_at >= $2`
	var n int64
	if err := s.pool.QueryRow(ctx, q, guildID, since).Scan(&n); err != nil {
		return 0, fmt.Errorf("storage: count incidents: %w", err)
	}
	return n, nil
}

