func (s *Store) TopDetectors(ctx context.Context, guildID string, since time.Time, limit int) ([]DetectorStat, error) {
	if limit <= 0 || limit > 20 {
		limit = 5
	}
	const q = `
		SELECT detector, COUNT(*)::bigint
		FROM incidents
		WHERE guild_id = $1 AND created_at >= $2
		GROUP BY detector
		ORDER BY COUNT(*) DESC
		LIMIT $3`

	rows, err := s.pool.Query(ctx, q, guildID, since, limit)
	if err != nil {
		return nil, fmt.Errorf("storage: top detectors: %w", err)
	}
	defer rows.Close()

	out := make([]DetectorStat, 0, limit)
	for rows.Next() {
		var d DetectorStat
		if err := rows.Scan(&d.Detector, &d.Count); err != nil {
			return nil, fmt.Errorf("storage: scan detector: %w", err)
		}
		out = append(out, d)
	}
	return out, rows.Err()
}

// ResolveIncident marca un incidente como resuelto por un moderador.
func (s *Store) ResolveIncident(ctx context.Context, id uuid.UUID, resolvedBy string) error {
	const q = `
		UPDATE incidents
		SET resolved_at = NOW(), resolved_by = $2
		WHERE id = $1 AND resolved_at IS NULL`

	tag, err := s.pool.Exec(ctx, q, id, resolvedBy)
	if err != nil {
		return fmt.Errorf("storage: resolve incident %s: %w", id, err)
	}
	if tag.RowsAffected() == 0 {
		return ErrIncidentNotFound
	}
	return nil
}

