func (s *Store) PurgeOldIncidents(ctx context.Context, before time.Time) (int64, error) {
	tag, err := s.pool.Exec(ctx, `DELETE FROM incidents WHERE created_at < $1`, before)
	if err != nil {
		return 0, fmt.Errorf("storage: purge incidents: %w", err)
	}
	return tag.RowsAffected(), nil
}
